import{z as B,x as n,o as A,c as d,q as t,j as s,D as E,d as r,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"蜂窝：RAN 与核心网","description":"","frontmatter":{"title":"蜂窝：RAN 与核心网","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cellular-ran-core.md","filePath":"cs/cellular-ran-core.md","lastUpdated":1791413859000}'),p={name:"cs/cellular-ran-core.md"};function P(C,a,c,N,h,u){const l=n("Mermaid");return A(),d("div",null,[a[2]||(a[2]=t('<h1 id="蜂窝-ran-与核心网" tabindex="-1">蜂窝：RAN 与核心网 <a class="header-anchor" href="#蜂窝-ran-与核心网" aria-label="Permalink to &quot;蜂窝：RAN 与核心网&quot;">​</a></h1><div class="epigraph"><p>空口在基站结束；用户的会话、鉴权与路由在核心网。RAN 与核心的接口让无线跳可以换代而不改「号码与数据」的合同。</p><footer>—— 据 3GPP TS 23.501（5G 架构）与 LTE EPC 对照；Kurose and Ross 蜂窝节整理</footer></div><p><a href="/cs/bluetooth-ble">上一课</a> 是无牌照短距。手机要移动、要计费、要跨城。缺口是<strong>蜂窝两段</strong>：RAN（UE–gNB/eNB）与核心（EPC 或 5GC）。本课不把网络切片 SLA 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Wi‑Fi 的「核心」往往是一台路由器加 DHCP。蜂窝：空口调度、切换、无线承载在 RAN；附着、会话、策略、对互联网的 PDU 会话在核心。<span class="marginnote">「RAN」翻译过来就是「无线接入网」：管你手机到基站之间那一跳——调度、功率、切换都归它。「核心网」则是基站背后的总部：你是谁（鉴权）、流量从哪个口出去（会话锚点）、怎么计费，全在这里办。手机里的「信号」只是 RAN 那一段，办业务要靠核心。</span>用户 IP 通常在核心锚点分配，基站像一跳隧道端——对照后课 GRE/GTP。移动性：换基站不换 IP 锚，才像「一直在线」。这不是 MAC 学习能做的：地址在三层锚，不是二层泛洪。</p><p><span class="marginnote">LTE：eNB + EPC（MME/SGW/PGW）。5G：gNB + AMF/SMF/UPF。本课钉分工，不背网元缩写表。</span></p><h3 id="基站不是交换机" tabindex="-1">基站不是交换机 <a class="header-anchor" href="#基站不是交换机" aria-label="Permalink to &quot;基站不是交换机&quot;">​</a></h3><p>用户 IP 在核心锚，换 gNB 不换锚。空口 \\(C\\) 与核心转发是两段预算。鉴权在核心，RAN 只消耗密钥。不要把 5G 写成更快 Wi‑Fi。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：UE ↔ RAN ↔ 核心 ↔ 互联网。对照 802.11：AP 桥到同一广播域；gNB 不把以太网洪泛到全国。鉴权在核心，空口只消耗密钥。容量：小区 \\(B\\) 与干扰决定空口 \\(C\\)，核心是交换与策略。</p>',10)),(A(),s(o,null,{default:E(()=>[i(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20UE%5B%22%E7%BB%88%E7%AB%AF%22%5D%20--%3E%20RAN%5B%22RAN%20%E8%B0%83%E5%BA%A6%E4%B8%8E%E6%97%A0%E7%BA%BF%22%5D%0A%20%20RAN%20--%3E%20CORE%5B%22%E6%A0%B8%E5%BF%83%3A%20%E4%BC%9A%E8%AF%9D%E4%B8%8E%E9%94%9A%E7%82%B9%22%5D%0A%20%20CORE%20--%3E%20INET%5B%22%E4%BA%92%E8%81%94%E7%BD%91%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"自协商变成能力与频段登记。PFC 无对应物；无线用调度与 QoS 承载。TCP 看到的 RTT 含空口调度时延，后课无线 TCP 会收回。主干 NAT 课：运营商常在锚点后做 NAT，与家庭路由同类但规模不同。",-1)),a[5]||(a[5]=e("p",null,"切换：RAN 先保住无线，核心更新转发；失败才掉 PDU 会话。GTP 隧道把基站接到锚点，中间仍是 IP 转发，不是 MAC 学习。",-1)),(A(),s(o,null,{default:E(()=>[i(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22UE%20%E5%9C%A8%E6%97%A7%20gNB%20%E4%B8%8A%E6%9C%89%E4%BC%9A%E8%AF%9D%22%5D%20--%3E%20MEAS%5B%22%E6%B5%8B%E9%87%8F%E6%8A%A5%E5%91%8A%EF%BC%9A%E9%82%BB%E5%8C%BA%E4%BF%A1%E5%8F%B7%E6%9B%B4%E5%BC%BA%22%5D%0A%20%20MEAS%20--%3E%20HO%5B%22%E5%88%87%E6%8D%A2%E5%86%B3%E5%AE%9A%EF%BC%9A%E7%9B%AE%E6%A0%87%20gNB%20%E5%85%88%E5%A4%87%E5%A5%BD%22%5D%0A%20%20HO%20--%3E%20W%5B%22%E6%97%A0%E7%BA%BF%E4%BE%A7%E5%88%87%E5%88%B0%E6%96%B0%20gNB%22%5D%0A%20%20W%20--%3E%20UP%5B%22%E6%A0%B8%E5%BF%83%E6%9B%B4%E6%96%B0%20GTP%20%E9%9A%A7%E9%81%93%E7%AB%AF%E7%82%B9%22%5D%0A%20%20UP%20--%3E%20KEEP%5B%22IP%20%E9%94%9A%E7%82%B9%E4%B8%8D%E5%8F%98%EF%BC%9A%E4%BC%9A%E8%AF%9D%E4%B8%8D%E6%96%AD%22%5D%0A%20%20HO%20-.-%3E%7C%22%E5%87%86%E5%A4%87%E6%88%96%E6%89%A7%E8%A1%8C%E5%A4%B1%E8%B4%A5%22%7C%20DROP%5B%22%E6%8E%89%20PDU%20%E4%BC%9A%E8%AF%9D%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">切换可以类比连锁酒店的入住转移：前台发现另一家分店更合适，先把那边的房间备好，你拎包过去（无线侧先换），而会员账号与账单地址不变（核心锚点不动）——所以「换店不换号」，正在下载的文件不会断。图里虚线那条失败路径，对应正文「失败才掉 PDU 会话」。</span></p><p>计费与政策在核心执行，空口只执行已授权的 QoS 规则。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IMS 语音全程。5G 切片与 URLLC 是下一课。后课默认：蜂窝 = RAN + 核心锚点；基站不是以太网交换机。</p><p>不要把「5G 等于更快 Wi‑Fi」当架构结论。</p><p><span class="marginnote">为什么这句要反复强调：把 5G 当「更快的 Wi‑Fi」看，会漏掉「IP 锚在核心、换基站不换 IP」这条主线——Wi‑Fi 的 AP 只把设备桥进一个局域网，蜂窝基站背后却是完整的鉴权、会话与计费体系。带着错误模型往后学，切片与移动性两课都接不上。</span></p><p>下一课<a href="/cs/5g-slicing">5G 切片与 URLLC</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RAN 管空口；核心管会话、移动性锚与出网。</li><li>用户 IP 在锚点，不靠二层洪泛跨城。</li><li>空口 \\(C\\) 与核心转发是两段预算。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：3GPP TS 23.501；Kurose and Ross。</li></ul>',9))])}const T=B(p,[["render",P]]);export{m as __pageData,T as default};
